import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log


def test_last_duplicate_wins_before_sorting_by_day_and_id():
    old = {"id": "a", "day": 5, "converted": False}
    new = {"id": "a", "day": 2, "converted": True}
    same_day = {"id": "b", "day": 2, "converted": False}
    earlier = {"id": "c", "day": 1, "converted": False}
    assert dedupe_sessions([same_day, old, earlier, new]) == [earlier, new, same_day]


def test_parse_ignores_comments_and_blanks_and_strips_fields():
    assert parse_session_log(["  # comment", "", " \t", " x , 2 , 0 ", " y , 4 , "]) == [
        {"id": "x", "day": 2, "converted": False},
        {"id": "y", "day": 4, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,2", "a,2,0,1", "a,no,1"])
def test_parse_errors_include_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# heading", "a,1,1", "  ", bad_line])


def test_daily_counts_include_zero_days_and_ignore_out_of_range_events():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,3,", "e,4,1"])
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []
