from sales_dashboard.loader import parse_session_log
from sales_dashboard.metrics import conversion_rate_by_group, conversions_in_window, longest_conversion_streak
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_summary_weights_sessions_and_uses_calendar_days():
    groups = {"a": parse_session_log(["x,1,1", "y,5,0"]), "b": parse_session_log(["z,4,1"]), "c": []}
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({"a": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_statistics_handle_empty_groups_and_ties():
    groups = {"z": [{"converted": False}], "b": [{"converted": True}], "empty": [], "a": [{"converted": True}]}
    assert top_converting_groups(groups, 5) == ["a", "b", "z"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 1.0), ("empty", None), ("z", 0.0)]


def test_window_boundaries():
    assert conversions_in_window([4, 2], 0) == 0
    assert conversions_in_window([4, 2], 1) == 2
    assert conversions_in_window([4, 2], 3) == 6


def test_streak_counts_only_consecutive_positive_days():
    assert longest_conversion_streak([1, 0, 2, 1, -1, 1]) == 2
    assert longest_conversion_streak([]) == 0
